import React, { useState, useEffect } from 'react';
import InternshipCard from '../components/InternshipCard'; // تأكد من المسار الصحيح
import Button from '../components/Button'; // تأكد من المسار الصحيح

const OpportunitiesPage = () => {
  // استخدام useState
  const [opportunities, setOpportunities] = useState([]);

  // استخدام useEffect
  useEffect(() => {
    // هنا يمكنك جلب البيانات أو إجراء عمليات جانبية
    setOpportunities(allOpportunities); // على سبيل المثال، تعيين البيانات الوهمية
  }, []);

  const allOpportunities = [
    {
      id: 1,
      title: "تدريب تطوير واجهات أمامية",
      company: "شركة الابتكار الرقمي",
      location: "الرياض، السعودية (عن بعد)",
      duration: "3 أشهر",
      stipend: "مدفوع",
      skills: ["React", "JavaScript", "Tailwind CSS"],
      description: "تدريب عملي باستخدام أحدث التقنيات",
      postedDate: "منذ يومين",
      type: "تدريب",
      category: "تطوير الويب",
    },
    // يمكنك إضافة المزيد من الفرص هنا
  ];

  return (
    <div>
      <h1>Opportunities</h1>
      {/* مثال على استخدام InternshipCard */}
      {opportunities.map(opportunity => (
        <InternshipCard key={opportunity.id} opportunity={opportun} />
      ))}
      {/* مثال على استخدام Button */}
      <Button text="Load More" onClick={() => console.log("Load More")} />
    </div>
  );
};

export default OpportunitiesPage;
